#!/usr/bin/env node
// check-contrast.js — the gate that would have caught brilliant-on-grey.
//
// 2026-10-14: PN02 shipped brilliant-green (#00D639) icons on a light-grey
// (#F2F5F6) stripe at 1.8:1 — invisible to every existing gate (copy sync,
// bindings, sync-check, and verify-section all passed: the classes were
// right, the ASSET color was wrong). This gate pins icon-asset fills and
// text colors against the stripe background as WCAG ratios, in a real
// browser, from the same terms.json oracle the other tools use.
//
// WHAT IT CHECKS (per component `figma/terms.json` `theme` block):
//   icons: every fill painted by the section's SVG assets vs the computed
//     stripe background, min 3.0 (WCAG 1.4.11 non-text graphics)
//   texts: every listed selector's computed color vs background, min 4.5
//     (WCAG 1.4.3 normal text; alpha is blended over the bg first)
// A theme change (dark<->light) must move bg + icons + text together; any
// one left behind fails loudly here instead of shipping quietly.
//
// USAGE
//   node tooling/check-contrast.js --selftest
//   node tooling/check-contrast.js --comp pn02-highlights-6col --url http://127.0.0.1:8901/ongoing_project/cpp/customer-payment-services/
// Exit: 0 pass, 1 contrast FAIL, 2 operator error, 0 + loud SKIP without Chrome.
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const argv = process.argv.slice(2);
const has = f => argv.includes(f);
const val = (f, d) => { const i = argv.indexOf(f); return i === -1 ? d : argv[i + 1]; };

// ------------------------------------------------------------- pure core ---
function parseColor(s) {
  s = String(s).trim().toLowerCase();
  const named = { white: [255, 255, 255, 1], black: [0, 0, 0, 1] };
  if (named[s]) return named[s];
  let m = s.match(/^#([0-9a-f]{6})$/);
  if (m) return [parseInt(m[1].slice(0, 2), 16), parseInt(m[1].slice(2, 4), 16), parseInt(m[1].slice(4, 6), 16), 1];
  m = s.match(/^#([0-9a-f]{3})$/);
  if (m) return [0, 1, 2].map(i => parseInt(m[1][i] + m[1][i], 16)).concat(1);
  m = s.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)(?:\s*,\s*([\d.]+))?\s*\)$/);
  if (m) return [+m[1], +m[2], +m[3], m[4] === undefined ? 1 : +m[4]];
  return null;
}
function luminance([r, g, b]) {
  const f = c => { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}
// fg may carry alpha: blend over opaque bg first (how the browser paints it).
function ratio(fgStr, bgStr) {
  const fg = parseColor(fgStr), bg = parseColor(bgStr);
  if (!fg || !bg) return null;
  const a = fg[3];
  const eff = [0, 1, 2].map(i => fg[i] * (1 - a) + bg[i] * a);
  const L1 = luminance(eff), L2 = luminance(bg.slice(0, 3));
  return (Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05);
}
// SVG asset fills: strip <defs> (clip paths paint nothing), collect fills.
function svgFills(text) {
  const noDefs = text.replace(/<defs[\s\S]*?<\/defs>/gi, '');
  const out = new Set();
  (noDefs.match(/fill\s*=\s*"([^"]+)"/gi) || []).forEach(m => {
    const c = m.split('"')[1].toLowerCase();
    if (c !== 'none') out.add(c);
  });
  (noDefs.match(/style\s*=\s*"[^"]*fill\s*:\s*([^;"]+)/gi) || []).forEach(m => {
    const c = m.split(':').pop().trim().toLowerCase();
    if (c !== 'none') out.add(c);
  });
  return [...out];
}

function selftest() {
  let pass = 0, fail = 0;
  const t = (n, cond, extra) => {
    if (cond) pass++;
    else { fail++; console.log(`  FAIL ${n}${extra === undefined ? '' : ' got ' + extra}`); }
  };
  console.log('WCAG math');
  t('black/white is 21', Math.abs(ratio('#000000', '#ffffff') - 21) < 0.01, ratio('#000000', '#ffffff'));
  const jade = ratio('#008146', '#F2F5F6');
  t('jade on light-grey passes text bar', jade >= 4.5 && jade < 4.7, jade);
  const bril = ratio('#00D639', '#F2F5F6');
  t('brilliant on light-grey fails graphics bar', bril !== null && bril < 3.0, bril);
  t('identical colors are 1', Math.abs(ratio('#F2F5F6', '#f2f5f6') - 1) < 0.001);
  const ink = ratio('rgba(0, 0, 0, 0.9)', 'rgb(242, 245, 246)');
  t('90%-black body text passes', ink !== null && ink >= 4.5, ink);
  t('bad color is null', ratio('nonsense', '#fff') === null);
  console.log('SVG fill extraction');
  const fills = svgFills('<svg fill="none"><defs><rect fill="white"/></defs><path fill="#008146"/><path fill="#008146"/></svg>');
  t('defs stripped, fills deduped', JSON.stringify(fills) === JSON.stringify(['#008146']), JSON.stringify(fills));
  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
}

// ------------------------------------------------------------------ I/O ---
async function run(comp, url, widths) {
  let puppeteer;
  try { puppeteer = require(path.join(ROOT, 'tooling', 'node_modules', 'puppeteer-core')); }
  catch { console.log('SKIP: puppeteer-core unavailable — contrast check NOT run (needs Chrome)'); process.exit(0); }
  const termsPath = path.join(ROOT, 'components', comp, 'figma', 'terms.json');
  if (!fs.existsSync(termsPath)) { console.error(`no terms.json for ${comp}`); process.exit(2); }
  const theme = JSON.parse(fs.readFileSync(termsPath, 'utf8')).theme;
  if (!theme) { console.error(`${comp}: terms.json has no theme block`); process.exit(2); }
  const exe = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
  if (!fs.existsSync(exe)) { console.log('SKIP: Chrome unavailable — contrast check NOT run'); process.exit(0); }

  let fails = 0;
  // icon assets: pure file I/O, width-independent (fail fast before Chrome)
  const iconColors = new Set();
  for (const f of (theme.icons || {}).files || []) {
    const fp = path.join(ROOT, theme.pageDir, f);
    if (!fs.existsSync(fp)) { console.log(`FAIL icon asset missing: ${f}`); fails++; continue; }
    svgFills(fs.readFileSync(fp, 'utf8')).forEach(c => iconColors.add(`${f}:${c}`));
  }
  if (!iconColors.size && fails === 0) { console.log('FAIL: no icon fills found'); fails++; }

  let browser;
  try {
    browser = await puppeteer.launch({ executablePath: exe, args: ['--no-sandbox', '--disable-gpu'] });
    const page = await browser.newPage();
    for (const w of widths) {
      await page.setViewport({ width: w, height: 900 });
      await page.goto(url, { waitUntil: 'networkidle0', timeout: 60000 });
      const got = await page.evaluate(sel => getComputedStyle(document.querySelector(sel)).backgroundColor, theme.bgSel).catch(() => null);
      if (got === null) { console.log(`FAIL ${w}: section ${theme.bgSel} missing`); fails++; continue; }
      console.log(`[${w}] bg ${theme.bgSel} = ${got}`);
      for (const ic of iconColors) {
        const [f, c] = ic.split(/:(?=#|\w)/);
        const r = ratio(c, got);
        const ok = r !== null && r >= (theme.icons.min || 3.0);
        console.log(`  ${ok ? 'PASS' : 'FAIL'} icon ${f} ${c} vs bg = ${r === null ? 'unparseable' : r.toFixed(2)} (min ${(theme.icons.min || 3.0).toFixed(1)})`);
        if (!ok) fails++;
      }
      const texts = await page.evaluate(sel => {
        const out = {};
        const t = document.querySelector(sel + ' .hero-title-text-inner');
        const b = document.querySelector(sel + ' .score-highlight-body');
        if (t) out.title = getComputedStyle(t).color;
        if (b) { out.body = getComputedStyle(b).color; out.bodyWeight = getComputedStyle(b).fontWeight; }
        return out;
      }, theme.bgSel);
      for (const tx of theme.texts || []) {
        const key = tx.key;
        if (!texts[key]) { console.log(`  FAIL text ${key}: selector missing`); fails++; continue; }
        const r = ratio(texts[key], got);
        const ok = r !== null && r >= (tx.min || 4.5);
        console.log(`  ${ok ? 'PASS' : 'FAIL'} text ${key} ${texts[key]} vs bg = ${r === null ? 'unparseable' : r.toFixed(2)} (min ${(tx.min || 4.5).toFixed(1)})`);
        if (!ok) fails++;
      }
      if (texts.bodyWeight) console.log(`  info body fontWeight = ${texts.bodyWeight}`);
    }
  } finally { if (browser) await browser.close(); }
  if (fails) { console.log(`${fails} contrast failure(s) (exit 1)`); process.exit(1); }
  console.log('CONTRAST CLEAN');
  process.exit(0);
}

if (has('--selftest')) selftest();
else {
  const comp = val('--comp', null), url = val('--url', null);
  if (!comp || !url) { console.error('usage: --comp <name> --url <http://…> [--widths 1920,390] | --selftest'); process.exit(2); }
  run(comp, url, val('--widths', '1920,390').split(',').map(Number)).catch(e => { console.error('ERROR ' + e.message.slice(0, 120)); process.exit(2); });
}

