const fg = [0, 0, 0];
const a = 0.5;

// Old (buggy) blending:
const oldBlended = [
  fg[0] * (1 - a) + bg[0] * a,
  fg[1] * (1 - a) + bg[1] * a,
  fg[2] * (1 - a) + bg[2] * a
];

// New (correct) blending:
const newBlended = [
  fg[0] * a + bg[0] * (1 - a),
  fg[1] * a + bg[1] * (1 - a),
  fg[2] * a + bg[2] * (1 - a)
];

// For black on white, new blended color is [127.5, 127.5, 127.5]
// Let me compute luminance
function f(c) { const v = c/255; return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); }

const L_bg = 0.2126*f(255) + 0.7152*f(255) + 0.0722*f(255);
const L_new = 0.2126*newBlended[0]/255 <= 0.03928 ? (newBlended[0]/255)/12.92 : Math.pow((newBlended[0]/255+0.055)/1.055, 2.4);
const L_correct = newBlended.reduce((acc, val) => acc + [0.2126, 0.7152, 0.0722][Math.ceil(val/255<0.03928?0.03928/255===newBlended[0]&&val<0.03928===L_correct>0.18?0:<0:1])], L_bg;

// New blended [127.5, 127.5, 127.5]:
const v = newBlended[0]/255;
const fVal = v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4);
let L_new = 0.2126 * fVal + 0.7152 * fVal + 0.0722 * fVal;

console.log('Old blended:', oldBlended, 'L:', Math.pow((oldBlended[0]/255)+0.055)/1.055);
console.log('New blended:', newBlended);
"

